  "chunks": [
    {
      "chunk_type": "isnad",
      "arabic_text": "عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ [عَنِ ابْنِ أَبِي عُمَيْرٍ] عَنْ جَمِيلِ بْنِ دَرَّاجٍ عَنْ زُرَارَةَ عَنْ أَحَدِهِمَا ( عَلَيْهِمَا السَّلَامُ )",
      "translations": {
        "en": "Ali ibn Ibrahim, from his father, [from Ibn Abi Umeyr], from Jameel ibn Darraj, from Zurara, from one of the two Imams (peace be upon them)."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فِي رَجُلٍ أَعْتَقَ مَمْلُوكَهُ عِنْدَ مَوْتِهِ وَ عَلَيْهِ دَيْنٌ قَالَ إِنْ كَانَ قِيمَتُهُ مِثْلَ الَّذِي عَلَيْهِ وَ مِثْلَهُ جَازَ عِتْقُهُ وَ إِلَّا لَمْ يَجُزْ",
      "translations": {
        "en": "Regarding a man who emancipated his slave at the time of his death, and upon him was a debt. He (peace be upon him) said: 'If the slave's value was equal to what was upon him, and like it, his emancipation is valid; otherwise, it is not valid.'"
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "This hadith establishes the legal ruling for the emancipation (itq) of a slave by a master who dies with outstanding debts. The emancipation is considered valid if the slave's market value is sufficient to cover the debt; if the value is insufficient, the emancipation is not valid, meaning the debt takes precedence.",
      "seo_question": "What is the ruling on freeing a slave if the owner dies with unpaid debts?",
      "key_terms": {
        "أَعْتَقَ": "Emancipated/freed",
        "مَمْلُوكَهُ": "His slave",
        "عِنْدَ مَوْتِهِ": "At the time of his death",
        "دَيْنٌ": "Debt",
        "قِيمَتُهُ": "His value (market price)",
        "جَازَ": "It is valid/permitted",
